// Decimal Integer Literals

// Basic assignment (default type is int)
int standard_int = 42;
constexpr int COUNT = 1000;

// Suffixes enforce specific types
unsigned int u_val = 10U;     // unsigned
long l_val         = 20L;     // long
long long ll_val   = 30LL;    // long long
unsigned long long ull_val = 40ULL;

// Literal exceeding int capacity defaults to long/long long
// Depending on compiler architecture/standard
auto big_num = 3000000000;
auto specified_big = 3000000000LL;

enum ErrorCode { ERR_FILE_NOT_FOUND = 404 };
int arr[128]; // Size defined by decimal literal
// Zero is a valid decimal literal
int zero_val = 0;
